#!/usr/bin/env python3
import argparse
import hashlib
import json
import os
import re
import shutil
import signal
import sqlite3
import statistics
import subprocess
import sys
import tempfile
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
REPO_ROOT = HERE.parents[2]
TMP_ROOT = HERE / "tmp"
TMP_ROOT.mkdir(parents=True, exist_ok=True)
os.environ["TMPDIR"] = str(TMP_ROOT)
tempfile.tempdir = str(TMP_ROOT)
sys.path.insert(0, str(REPO_ROOT / "scripts"))
import benchmark_quality
from benchmark_quality import PersistentMcpClient, percentile

BASELINE_BINARY = HERE / "build" / "baseline-target" / "release" / "code-kb"
PLAN_PATH = HERE / "benchmark-plan.json"
SETUP_PATH = HERE / "setup.json"
SAMPLES = 20
REQUEST_TIMEOUT_SECONDS = 120
READINESS_TIMEOUT_SECONDS = 300
INDEXING_NOTICE = re.compile(r"^Indexing .+ started; call again in a few seconds\.$")
CAPTURED_RESPONSES: list[dict[str, Any]] = []
ORIGINAL_MCP_RESULT = benchmark_quality.mcp_result


def capture_mcp_result(response: dict[str, Any], request_id: int, operation: str) -> dict[str, Any]:
    CAPTURED_RESPONSES.append(response)
    return ORIGINAL_MCP_RESULT(response, request_id, operation)


benchmark_quality.mcp_result = capture_mcp_result


class RequestTimeout(TimeoutError):
    pass


class Journal:
    def __init__(self, path: Path):
        self.path = path
        self.stream = path.open("x", encoding="utf-8")

    def write(self, event: str, **fields: Any) -> None:
        record = {"event": event, "at": datetime.now(timezone.utc).isoformat(), **fields}
        self.stream.write(json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n")
        self.stream.flush()
        os.fsync(self.stream.fileno())
        progress = {key: record[key] for key in (
            "event", "at", "corpus", "side", "workload_id", "phase", "sample", "tool",
            "status", "elapsed_ms", "index_sha256", "counts", "source", "destination",
            "result_path", "journal_path",
        ) if key in record}
        outcome = record.get("outcome")
        if isinstance(outcome, dict):
            for key in ("status", "elapsed_ms", "result_count"):
                if key in outcome:
                    progress[key] = outcome[key]
        print(json.dumps(progress, ensure_ascii=False, separators=(",", ":")), flush=True)

    def close(self) -> None:
        self.stream.close()


def request_with_deadline(client: PersistentMcpClient, name: str, args: dict[str, Any], seconds: float):
    def expire(signum, frame):
        raise RequestTimeout(f"request exceeded {seconds:.0f} seconds")

    previous_handler = signal.signal(signal.SIGALRM, expire)
    previous_timer = signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        response, elapsed_ms = client.call_tool(name, args)
        return response, elapsed_ms
    except RequestTimeout:
        raise
    except Exception:
        raise
    finally:
        signal.setitimer(signal.ITIMER_REAL, *previous_timer)
        signal.signal(signal.SIGALRM, previous_handler)


def result_text(result: dict[str, Any]) -> str:
    return "\n".join(
        block.get("text", "")
        for block in result.get("content", [])
        if isinstance(block, dict) and isinstance(block.get("text"), str)
    )


def replace_root(value: Any, root: str) -> Any:
    if isinstance(value, str):
        return value.replace(root, "<project_root>")
    if isinstance(value, list):
        return [replace_root(item, root) for item in value]
    if isinstance(value, dict):
        return {key: replace_root(item, root) for key, item in value.items()}
    return value


def blast_section_counts(text: str) -> dict[str, int]:
    patterns = {
        "likely_tests": r"^### Likely Tests to Run \((\d+) returned\)$",
        "downstream_impact": r"^### Downstream Impact \((\d+) returned\)$",
    }
    counts = {}
    for name, pattern in patterns.items():
        match = re.search(pattern, text, re.MULTILINE)
        if match:
            counts[name] = int(match.group(1))
    return counts


def result_count(result: dict[str, Any], text: str) -> int | None:
    blast_counts = blast_section_counts(text)
    if blast_counts:
        return sum(blast_counts.values())
    match = re.search(
        r"^(?:Callers|Callees) of .+?\((\d+) found\):$",
        text,
        re.MULTILINE | re.IGNORECASE,
    )
    if match:
        return int(match.group(1))
    structured = result.get("structuredContent")
    if isinstance(structured, dict):
        for key in ("references", "results", "symbols", "rows", "tests", "callers", "callees", "matches", "facts"):
            value = structured.get(key)
            if isinstance(value, list):
                return len(value)
    match = re.search(
        r"\b(?:Found|Showing)\s+(\d+)\s+(?:references?|symbols?|rows?|tests?|files?|results?)\b",
        text,
        re.IGNORECASE,
    )
    return int(match.group(1)) if match else None


def summarize_result(response: dict[str, Any], root: str) -> dict[str, Any]:
    result = response.get("result", {})
    text = result_text(result)
    normalized = replace_root(result, root)
    encoded = json.dumps(normalized, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    return {
        "output_sha256": hashlib.sha256(encoded).hexdigest(),
        "result_count": result_count(result, text),
        "section_counts": blast_section_counts(text),
        "content_blocks": len(result.get("content", [])),
        "text_line_count": sum(bool(line.strip()) for line in text.splitlines()),
        "text": text,
    }


def normalized_memory(client: PersistentMcpClient | None) -> dict[str, float | None] | None:
    if client is None or client.proc.poll() is not None:
        return None
    values = client.get_live_memory()
    return {key: (value if value > 0 else None) for key, value in values.items()}


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(8 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def git_state(path: Path) -> dict[str, Any]:
    def git(*args: str) -> str:
        return subprocess.run(
            ["git", "-C", str(path), *args],
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip()

    porcelain = git("status", "--porcelain")
    return {
        "path": str(path),
        "branch": git("branch", "--show-current"),
        "head": git("rev-parse", "HEAD"),
        "status_short_branch": git("status", "--short", "--branch"),
        "dirty": bool(porcelain),
        "porcelain": porcelain.splitlines(),
    }


def extractor_info(candidate_binary: Path) -> dict[str, Any] | None:
    candidates = []
    configured = os.environ.get("JULIE_EXTRACT_BIN")
    if configured:
        candidates.append(Path(configured).expanduser())
    candidates.append(candidate_binary.parent / "julie-extract")
    candidates.extend(parent / ".tools" / "julie-extract" for parent in candidate_binary.parents)
    path_binary = shutil.which("julie-extract")
    if path_binary:
        candidates.append(Path(path_binary))
    for candidate in candidates:
        if candidate.is_file():
            version = subprocess.run(
                [str(candidate), "--version"],
                check=True,
                capture_output=True,
                text=True,
            ).stdout.strip()
            return {
                "path": str(candidate.resolve()),
                "version": version,
                "sha256": file_sha256(candidate),
            }
    return None


class Session:
    def __init__(self, side: str, binary: Path, root: Path, journal: Journal):
        self.side = side
        self.binary = binary
        self.root = root
        self.journal = journal
        self.client: PersistentMcpClient | None = None
        self.starts: list[dict[str, Any]] = []
        self.recoveries: list[dict[str, Any]] = []

    def close_client(self) -> None:
        if self.client is not None:
            self.client.close()
            self.client = None

    def start(self) -> dict[str, Any]:
        self.journal.write(
            "session_starting",
            side=self.side,
            corpus=self.root.name,
            root=str(self.root),
            binary=str(self.binary),
        )
        started = time.perf_counter()
        self.client = PersistentMcpClient(str(self.binary), str(self.root))
        spawn_ms = (time.perf_counter() - started) * 1000.0
        init_ms = self.client.initialize()
        record = {
            "process_spawn_ms": spawn_ms,
            "initialize_ms": init_ms,
            "started_at": datetime.now(timezone.utc).isoformat(),
        }
        self.starts.append(record)
        self.journal.write(
            "session_ready",
            side=self.side,
            corpus=self.root.name,
            root=str(self.root),
            process_spawn_ms=spawn_ms,
            initialize_ms=init_ms,
        )
        return record


def call_once(
    session: Session,
    workload: dict[str, Any],
    journal: Journal,
    phase: str,
    sample: int | None = None,
    timeout_seconds: float = REQUEST_TIMEOUT_SECONDS,
):
    if session.client is None:
        session.start()
    client = session.client
    started = time.perf_counter()
    CAPTURED_RESPONSES.clear()
    request_context = {
        "side": session.side,
        "workload_id": workload["id"],
        "phase": phase,
        "sample": sample,
        "tool": workload["tool"],
        "arguments": workload["arguments"],
        "timeout_seconds": timeout_seconds,
    }
    journal.write("request_started", **request_context)
    try:
        response, elapsed_ms = request_with_deadline(
            client, workload["tool"], workload["arguments"], timeout_seconds
        )
        summary = summarize_result(response, str(session.root))
        text = summary.pop("text")
        summary["raw_response"] = CAPTURED_RESPONSES[-1] if CAPTURED_RESPONSES else response
        if INDEXING_NOTICE.match(text.strip()):
            outcome = {"status": "indexing", "elapsed_ms": elapsed_ms, "text": text, **summary}
        else:
            outcome = {"status": "completed", "elapsed_ms": elapsed_ms, **summary}
        journal.write("request_outcome", **request_context, outcome=outcome)
        return outcome, response
    except RequestTimeout as exc:
        elapsed_ms = (time.perf_counter() - started) * 1000.0
        session.close_client()
        raw_response = CAPTURED_RESPONSES[-1] if CAPTURED_RESPONSES else None
        outcome = {
            "status": "timeout",
            "elapsed_ms": elapsed_ms,
            "error": str(exc),
            "raw_response": raw_response,
        }
        journal.write("request_outcome", **request_context, outcome=outcome)
        return outcome, raw_response
    except Exception as exc:
        elapsed_ms = (time.perf_counter() - started) * 1000.0
        if session.client is not None and session.client.proc.poll() is not None:
            session.close_client()
        raw_response = CAPTURED_RESPONSES[-1] if CAPTURED_RESPONSES else None
        outcome = {
            "status": "error",
            "elapsed_ms": elapsed_ms,
            "error": str(exc),
            "raw_response": raw_response,
        }
        journal.write("request_outcome", **request_context, outcome=outcome)
        return outcome, raw_response


def await_completed(
    session: Session,
    workload: dict[str, Any],
    events: list[dict[str, Any]],
    phase: str,
    journal: Journal,
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    deadline = time.monotonic() + READINESS_TIMEOUT_SECONDS
    while time.monotonic() < deadline:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        outcome, response = call_once(
            session, workload, journal, phase, timeout_seconds=min(REQUEST_TIMEOUT_SECONDS, remaining)
        )
        if outcome["status"] == "indexing":
            events.append({"phase": phase, **outcome})
            time.sleep(min(0.25, max(0.0, deadline - time.monotonic())))
            continue
        if outcome["status"] == "timeout":
            events.append({"phase": phase, **outcome})
            if session.client is None:
                try:
                    session.start()
                except Exception as exc:
                    events.append({"phase": phase, "status": "restart_error", "error": str(exc)})
                    break
            continue
        return outcome, response
    return {"status": "readiness_timeout", "elapsed_ms": None}, None


def make_index_copy(source_root: Path, destination: Path, journal: Journal | None = None) -> dict[str, Any]:
    source_db = source_root / ".code-kb" / "artifact.db"
    if not source_db.is_file():
        raise FileNotFoundError(source_db)
    if destination.exists():
        raise FileExistsError(destination)

    def ignore(directory: str, names: list[str]) -> set[str]:
        if Path(directory) == source_root:
            return {name for name in names if name in {".code-kb", ".git"}}
        return {".git"} if ".git" in names else set()

    if journal is not None:
        journal.write("corpus_copy_started", source=str(source_root), destination=str(destination))
    shutil.copytree(source_root, destination, ignore=ignore)
    destination_db = destination / ".code-kb" / "artifact.db"
    destination_db.parent.mkdir(parents=True, exist_ok=True)
    (destination / ".code-kb" / ".gitignore").write_text("*\n", encoding="utf-8")
    source = sqlite3.connect(f"file:{source_db}?mode=ro", uri=True)
    target = sqlite3.connect(destination_db)
    try:
        source.backup(target, pages=16384, sleep=0.01)
    finally:
        target.close()
        source.close()
    for suffix in ("-wal", "-shm"):
        sidecar = Path(str(destination_db) + suffix)
        if sidecar.exists():
            sidecar.unlink()
    connection = sqlite3.connect(f"file:{destination_db}?mode=ro", uri=True)
    try:
        tables = {row[0] for row in connection.execute("select name from sqlite_master where type='table'")}
        counts = {
            table: connection.execute(f"select count(*) from {table}").fetchone()[0]
            for table in ("files", "symbols")
            if table in tables
        }
        sqlite_version = connection.execute("select sqlite_version()").fetchone()[0]
        pragma_user_version = connection.execute("pragma user_version").fetchone()[0]
        journal_mode = connection.execute("pragma journal_mode").fetchone()[0]
        metadata = dict(connection.execute("select key, value from artifact_metadata")) if "artifact_metadata" in tables else {}
    finally:
        connection.close()
    digest = hashlib.sha256()
    with destination_db.open("rb") as stream:
        for chunk in iter(lambda: stream.read(4 * 1024 * 1024), b""):
            digest.update(chunk)
    return {
        "root": str(destination),
        "index_path": str(destination_db),
        "index_sha256": digest.hexdigest(),
        "source_index_sha256": file_sha256(source_db),
        "index_bytes": destination_db.stat().st_size,
        "counts": counts,
        "journal_mode": journal_mode,
        "pragma_user_version": pragma_user_version,
        "artifact_schema_metadata": {
            key: metadata.get(key)
            for key in (
                "schema_version",
                "sqlite_schema_version",
                "extract_contract_version",
                "binary_version",
                "index_level",
                "fts_rule",
                "root_path",
            )
        },
        "python_sqlite_version": sqlite_version,
    }


def memory_snapshot(session: Session) -> dict[str, float | None] | None:
    return normalized_memory(session.client)


def summarize_samples(samples: list[dict[str, Any]]) -> dict[str, Any]:
    timings = [sample["elapsed_ms"] for sample in samples if sample.get("elapsed_ms") is not None]
    successes = [sample["elapsed_ms"] for sample in samples if sample["status"] == "completed"]
    return {
        "sample_count": len(samples),
        "completed_count": sum(sample["status"] == "completed" for sample in samples),
        "error_count": sum(sample["status"] == "error" for sample in samples),
        "timeout_count": sum(sample["status"] == "timeout" for sample in samples),
        "not_run_count": sum(sample["status"].startswith("not_run") for sample in samples),
        "all_outcome_median_ms": statistics.median(timings) if timings else None,
        "all_outcome_p95_ms": percentile(timings, 0.95) if len(timings) == SAMPLES else None,
        "completed_median_ms": statistics.median(successes) if successes else None,
        "completed_p95_ms": percentile(successes, 0.95) if successes else None,
        "distinct_completed_output_sha256": sorted({
            sample["output_sha256"] for sample in samples
            if sample["status"] == "completed" and sample.get("output_sha256")
        }),
    }


def prepare_run_copies(
    run_id: str,
    journal: Journal,
    setup: dict[str, Any],
) -> dict[str, dict[str, dict[str, Any]]]:
    copies: dict[str, dict[str, dict[str, Any]]] = {}
    for corpus in ("flask", "hermes"):
        source = HERE / "corpora" / corpus
        copies[corpus] = {}
        for side in ("baseline", "candidate"):
            destination = HERE / "run-copies" / run_id / side / corpus
            copies[corpus][side] = make_index_copy(source, destination, journal)
            expected_index = setup["corpora"][corpus]["index"]
            actual_index = copies[corpus][side]
            if actual_index["source_index_sha256"] != expected_index["sha256"]:
                raise RuntimeError(f"{corpus} source index changed since setup.json was captured")
            if actual_index["counts"] != expected_index["counts"]:
                raise RuntimeError(f"{corpus} index counts differ from setup.json")
            if actual_index["artifact_schema_metadata"] != expected_index["artifact_schema_metadata"]:
                raise RuntimeError(f"{corpus} artifact metadata differs from setup.json")
        if copies[corpus]["baseline"]["counts"] != copies[corpus]["candidate"]["counts"]:
            raise RuntimeError(f"{corpus} clone counts differ")
        if copies[corpus]["baseline"]["index_sha256"] != copies[corpus]["candidate"]["index_sha256"]:
            raise RuntimeError(f"{corpus} clone database hashes differ")
        journal.write(
            "corpus_copies_ready",
            corpus=corpus,
            index_sha256=copies[corpus]["baseline"]["index_sha256"],
            counts=copies[corpus]["baseline"]["counts"],
            artifact_schema_metadata=copies[corpus]["baseline"]["artifact_schema_metadata"],
        )
    return copies


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--candidate-binary", required=True, type=Path)
    parser.add_argument("--run-id", default=datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ"))
    parser.add_argument("--output", type=Path)
    options = parser.parse_args()
    candidate_binary = options.candidate_binary.resolve()
    if not BASELINE_BINARY.is_file():
        parser.error(f"baseline binary is missing: {BASELINE_BINARY}")
    if not candidate_binary.is_file():
        parser.error(f"candidate binary is missing: {candidate_binary}")
    plan = json.loads(PLAN_PATH.read_text(encoding="utf-8"))
    setup = json.loads(SETUP_PATH.read_text(encoding="utf-8"))
    if file_sha256(BASELINE_BINARY) != setup["baseline_source"]["binary"]["sha256"]:
        parser.error("baseline binary hash no longer matches setup.json")
    candidate_extractor = extractor_info(candidate_binary)
    if candidate_extractor is None:
        parser.error("candidate julie-extract binary could not be resolved")
    if candidate_extractor["version"] != setup["baseline_source"]["extractor"]["version"]:
        parser.error("candidate julie-extract version differs from the baseline")
    output_path = options.output or (HERE / "results" / f"{options.run_id}.json")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    journal_path = output_path.with_suffix(".events.jsonl")
    if (
        output_path.exists()
        or output_path.with_suffix(output_path.suffix + ".tmp").exists()
        or journal_path.exists()
    ):
        parser.error(f"result output already exists: {output_path}")
    journal = Journal(journal_path)
    journal.write(
        "run_started",
        run_id=options.run_id,
        result_path=str(output_path),
        plan_path=str(PLAN_PATH),
        setup_path=str(SETUP_PATH),
        temporary_directory=str(TMP_ROOT),
        settings={
            "samples_per_workload_and_binary": SAMPLES,
            "request_timeout_seconds": REQUEST_TIMEOUT_SECONDS,
            "readiness_timeout_seconds": READINESS_TIMEOUT_SECONDS,
            "warmups_per_workload_and_binary": 1,
            "session_order": "alternating by corpus",
            "paired_request_order": "alternating by workload and sample",
        },
        candidate_binary=str(candidate_binary),
    )
    copies = prepare_run_copies(options.run_id, journal, setup)
    sides = {
        "baseline": BASELINE_BINARY,
        "candidate": candidate_binary,
    }
    output: dict[str, Any] = {
        "created_at": datetime.now(timezone.utc).isoformat(),
        "run_id": options.run_id,
        "plan_path": str(PLAN_PATH),
        "checkpoint_journal": str(journal_path),
        "setup": setup,
        "settings": {
            "samples_per_workload_and_binary": SAMPLES,
            "request_timeout_seconds": REQUEST_TIMEOUT_SECONDS,
            "readiness_timeout_seconds": READINESS_TIMEOUT_SECONDS,
            "warmups_per_workload_and_binary": 1,
            "percentile": "nearest rank via benchmark_quality.percentile",
            "session_order": [],
            "paired_sample_call_order": [],
        },
        "binaries": {
            "baseline": setup["baseline_source"]["binary"],
            "candidate": {
                "path": str(candidate_binary),
                "version": subprocess.run(
                    [str(candidate_binary), "--version"],
                    check=True,
                    capture_output=True,
                    text=True,
                ).stdout.strip(),
                "sha256": file_sha256(candidate_binary),
                "extractor": candidate_extractor,
                "source_worktree": git_state(REPO_ROOT),
            },
        },
        "corpus_copies": copies,
        "measurements": [],
    }
    sessions: dict[tuple[str, str], Session] = {}
    try:
        for corpus_index, corpus in enumerate(("flask", "hermes")):
            start_order = ["baseline", "candidate"] if corpus_index % 2 == 0 else ["candidate", "baseline"]
            output["settings"]["session_order"].append({"corpus": corpus, "order": start_order})
            for side in start_order:
                session = Session(side, sides[side], Path(copies[corpus][side]["root"]), journal)
                sessions[(corpus, side)] = session
                session.start()

            workloads = [workload for workload in plan["workloads"] if workload["corpus"] == corpus]
            for workload_index, workload in enumerate(workloads):
                ready_order = (
                    ["baseline", "candidate"]
                    if (corpus_index + workload_index) % 2 == 0
                    else ["candidate", "baseline"]
                )
                per_side: dict[str, dict[str, Any]] = {}
                for side in ready_order:
                    session = sessions[(corpus, side)]
                    events: list[dict[str, Any]] = []
                    first, first_response = await_completed(session, workload, events, "first_request", journal)
                    warmup = None
                    if first["status"] != "readiness_timeout":
                        warmup, _ = await_completed(session, workload, events, "warmup", journal)
                    per_side[side] = {
                        "workload_id": workload["id"],
                        "corpus": corpus,
                        "binary": str(sides[side]),
                        "tool": workload["tool"],
                        "arguments": workload["arguments"],
                        "session_starts": session.starts,
                        "first_request": first,
                        "first_result": first_response,
                        "warmup": warmup,
                        "readiness_events": events,
                        "recovery_events": session.recoveries,
                        "memory_before": memory_snapshot(session),
                        "samples": [],
                        "memory_after": None,
                    }

                for sample_index in range(SAMPLES):
                    pair_order = (
                        ["baseline", "candidate"]
                        if (sample_index + corpus_index + workload_index) % 2 == 0
                        else ["candidate", "baseline"]
                    )
                    output["settings"]["paired_sample_call_order"].append(
                        {"workload_id": workload["id"], "sample": sample_index + 1, "order": pair_order}
                    )
                    for side in pair_order:
                        session = sessions[(corpus, side)]
                        record = per_side[side]
                        if record["first_request"]["status"] == "readiness_timeout":
                            sample = {"status": "not_run_readiness_timeout", "elapsed_ms": None}
                        else:
                            if session.client is None:
                                recovery_events: list[dict[str, Any]] = []
                                ready, _ = await_completed(session, workload, recovery_events, "recovery", journal)
                                if ready["status"] != "readiness_timeout":
                                    warm, _ = await_completed(session, workload, recovery_events, "recovery_warmup", journal)
                                    session.recoveries.append({
                                        "workload_id": workload["id"],
                                        "events": recovery_events,
                                        "ready": ready,
                                        "warmup": warm,
                                    })
                                else:
                                    session.recoveries.append({
                                        "workload_id": workload["id"],
                                        "events": recovery_events,
                                        "ready": ready,
                                    })
                            if session.client is None:
                                sample = {"status": "not_run_session_unavailable", "elapsed_ms": None}
                            else:
                                sample, _ = call_once(session, workload, journal, "measured", sample_index + 1)
                                if sample["status"] == "indexing":
                                    notice = {**sample, "phase": "measured_readiness", "workload_id": workload["id"]}
                                    record["readiness_events"].append(notice)
                                    ready, _ = await_completed(
                                        session, workload, record["readiness_events"], "measured_readiness", journal
                                    )
                                    if ready["status"] == "readiness_timeout":
                                        sample = {"status": "not_run_readiness_timeout", "elapsed_ms": None}
                                    elif session.client is None:
                                        sample = {"status": "not_run_session_unavailable", "elapsed_ms": None}
                                    else:
                                        sample, _ = call_once(session, workload, journal, "measured", sample_index + 1)
                        record["samples"].append({"sample": sample_index + 1, **sample})
                        journal.write(
                            "sample_checkpoint",
                            side=side,
                            workload_id=workload["id"],
                            sample=sample_index + 1,
                            outcome=sample,
                        )
                for side in ("baseline", "candidate"):
                    record = per_side[side]
                    record["memory_after"] = memory_snapshot(sessions[(corpus, side)])
                    record["summary"] = summarize_samples(record["samples"])
                    output["measurements"].append(record)
    finally:
        for session in sessions.values():
            session.close_client()

    temporary = output_path.with_suffix(output_path.suffix + ".tmp")
    temporary.write_text(json.dumps(output, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    temporary.replace(output_path)
    journal.write("run_complete", result_path=str(output_path))
    journal.close()
    print(json.dumps({"event": "run_complete", "result_path": str(output_path), "journal_path": str(journal_path)}), flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

