#!/usr/bin/env python3
"""Compare CLI reference JSON against a frozen, hand-labeled regression set."""

import argparse
import hashlib
import json
import os
import platform
import shutil
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path


HERE = Path(__file__).resolve().parent
REPO = HERE.parents[2]
DEFAULT_BASELINE = REPO / "target/receiver-reference-reliability/benchmark/build/baseline-target/release/code-kb"
DEFAULT_CANDIDATE = REPO / "target/release/code-kb"
PINNED_EXTRACTOR = REPO / ".tools/julie-extract"


def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def fixture_identity(root):
    files = [
        {"path": path.relative_to(root).as_posix(), "sha256": sha256(path), "size_bytes": path.stat().st_size}
        for path in sorted(root.rglob("*"))
        if path.is_file()
    ]
    digest = hashlib.sha256(json.dumps(files, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    return {"sha256": digest, "files": files}


def identity(row):
    return (
        row.get("from_symbol_name"),
        str(row.get("path", "")).replace("\\", "/").removeprefix("./"),
        row.get("start_line"),
    )


def labels_for(target, label):
    return {identity(row) for row in target["labels"][label]}


def command_for(binary, root, args):
    command = [
        str(binary),
        "--root",
        str(root),
        "--json",
        "refs",
        args["symbol"],
        "--direction",
        args["direction"],
        "--limit",
        str(args["limit"]),
    ]
    if "file" in args:
        command.extend(["--file", args["file"]])
    return command


def evaluate(target, rows):
    required = labels_for(target, "required_supported")
    forbidden = labels_for(target, "forbidden_wrong_receiver")
    candidates = labels_for(target, "unresolved_candidates")
    observed = {identity(row): row for row in rows}
    actual = set(observed)
    actual_supported = {
        key for key, row in observed.items() if "candidate" not in str(row.get("kind", ""))
    }
    true_positives = required & actual_supported
    false_positives = forbidden & actual
    false_negatives = required - actual_supported
    precision_denominator = len(true_positives) + len(false_positives)
    recall_denominator = len(true_positives) + len(false_negatives)
    expected_candidates_seen = candidates & actual
    candidate_kind_mismatches = {
        key for key in expected_candidates_seen if "candidate" not in str(observed[key].get("kind", ""))
    }
    unknown_rows = [
        {
            "classification": "expected_unresolved_candidate" if key in candidates else "unlabeled",
            "row": observed[key],
        }
        for key in sorted(actual - required - forbidden)
    ]
    unknown_rows.extend(
        {"classification": "required_identity_returned_as_candidate", "row": observed[key]}
        for key in sorted(required & actual - actual_supported)
    )
    return {
        "rows_returned": len(rows),
        "distinct_rows_returned": len(actual),
        "supported_subset": {
            "tp": len(true_positives),
            "fp": len(false_positives),
            "fn": len(false_negatives),
            "precision": len(true_positives) / precision_denominator if precision_denominator else None,
            "recall": len(true_positives) / recall_denominator if recall_denominator else None,
            "tp_rows": [observed[key] for key in sorted(true_positives)],
            "fp_rows": [observed[key] for key in sorted(false_positives)],
            "fn_rows": [dict(zip(("from_symbol_name", "path", "start_line"), key)) for key in sorted(false_negatives)],
        },
        "unresolved_candidate_subset": {
            "expected": len(candidates),
            "seen": len(expected_candidates_seen),
            "missing": [dict(zip(("from_symbol_name", "path", "start_line"), key)) for key in sorted(candidates - actual)],
            "candidate_kind_mismatches": [observed[key] for key in sorted(candidate_kind_mismatches)],
        },
        "unknown_rows": unknown_rows,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--baseline", type=Path, default=DEFAULT_BASELINE)
    parser.add_argument("--candidate", type=Path, default=DEFAULT_CANDIDATE)
    parser.add_argument("--extractor", type=Path, default=PINNED_EXTRACTOR)
    parser.add_argument("--timeout-seconds", type=int, default=120)
    parser.add_argument("--run-id", default=datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ"))
    args = parser.parse_args()

    binaries = {"baseline": args.baseline.resolve(), "candidate": args.candidate.resolve()}
    for label, binary in binaries.items():
        if not binary.is_file():
            parser.error(f"{label} binary is missing: {binary}")
    extractor = args.extractor.resolve()
    if not extractor.is_file():
        parser.error(f"pinned julie-extract binary is missing: {extractor}")

    manifest_path = HERE / "expected.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    run_root = HERE / "runs" / args.run_id
    if run_root.exists():
        parser.error(f"run output already exists: {run_root}")
    run_root.mkdir(parents=True)
    run_manifest = run_root / "expected.json"
    shutil.copy2(manifest_path, run_manifest)

    workspaces = {}
    for binary_label in binaries:
        for target in manifest["targets"]:
            case_name = Path(target["fixture"]).name
            key = (binary_label, case_name)
            if key in workspaces:
                continue
            destination = run_root / "workspaces" / binary_label / case_name
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copytree(HERE / target["fixture"], destination)
            (destination / "pyproject.toml").write_text("", encoding="utf-8")
            workspaces[key] = destination

    environment = os.environ.copy()
    environment["JULIE_EXTRACT_BIN"] = str(extractor)
    results = {
        "run_id": args.run_id,
        "started_at_utc": datetime.now(timezone.utc).isoformat(),
        "scope": "Only the frozen, hand-labeled receiver-reference regression fixtures.",
        "workspace_marker": "An empty pyproject.toml is added to each isolated CLI copy so the root satisfies CLI project validation.",
        "manifest": str(run_manifest),
        "source_manifest": str(manifest_path),
        "platform": platform.platform(),
        "python": sys.version,
        "extractor": {"path": str(extractor), "expected_version": "3.6.3", "sha256": sha256(extractor)},
        "binaries": {
            label: {"path": str(binary), "sha256": sha256(binary), "size_bytes": binary.stat().st_size}
            for label, binary in binaries.items()
        },
        "fixtures": {
            Path(target["fixture"]).name: fixture_identity(HERE / target["fixture"])
            for target in manifest["targets"]
        },
        "outcomes": [],
    }

    for target in manifest["targets"]:
        for binary_label, binary in binaries.items():
            workspace = workspaces[(binary_label, Path(target["fixture"]).name)]
            command = command_for(binary, workspace, target["tool_args"])
            outcome = {
                "binary": binary_label,
                "target_id": target["target_id"],
                "definition": target["definition"],
                "workspace": str(workspace),
                "command": command,
            }
            try:
                completed = subprocess.run(
                    command,
                    cwd=workspace,
                    env=environment,
                    capture_output=True,
                    text=True,
                    timeout=args.timeout_seconds,
                    check=False,
                )
                outcome.update({"return_code": completed.returncode, "stderr": completed.stderr})
                if completed.returncode == 0:
                    try:
                        rows = json.loads(completed.stdout)
                        if not isinstance(rows, list):
                            raise ValueError("CLI JSON result was not an array")
                        outcome["rows"] = rows
                        outcome["evaluation"] = evaluate(target, rows)
                    except (json.JSONDecodeError, ValueError) as error:
                        outcome.update({"error": f"invalid CLI JSON: {error}", "stdout": completed.stdout})
                else:
                    outcome.update({"error": "CLI returned nonzero status", "stdout": completed.stdout})
            except subprocess.TimeoutExpired as error:
                outcome.update({"error": "timeout", "timeout_seconds": args.timeout_seconds})
                outcome["stdout"] = error.stdout.decode(errors="replace") if isinstance(error.stdout, bytes) else error.stdout
                outcome["stderr"] = error.stderr.decode(errors="replace") if isinstance(error.stderr, bytes) else error.stderr
            results["outcomes"].append(outcome)

    comparisons = []
    for target in manifest["targets"]:
        by_binary = {
            outcome["binary"]: outcome
            for outcome in results["outcomes"]
            if outcome["target_id"] == target["target_id"]
        }
        baseline_rows = by_binary.get("baseline", {}).get("rows", [])
        candidate_rows = by_binary.get("candidate", {}).get("rows", [])
        baseline_by_key = {identity(row): row for row in baseline_rows}
        candidate_by_key = {identity(row): row for row in candidate_rows}
        common_keys = set(candidate_by_key) & set(baseline_by_key)
        comparisons.append({
            "target_id": target["target_id"],
            "baseline": by_binary.get("baseline", {}).get("evaluation"),
            "candidate": by_binary.get("candidate", {}).get("evaluation"),
            "added_in_candidate": [candidate_by_key[key] for key in sorted(set(candidate_by_key) - set(baseline_by_key))],
            "removed_in_candidate": [baseline_by_key[key] for key in sorted(set(baseline_by_key) - set(candidate_by_key))],
            "changed_rows": [
                {"baseline": baseline_by_key[key], "candidate": candidate_by_key[key]}
                for key in sorted(common_keys)
                if baseline_by_key[key] != candidate_by_key[key]
            ],
        })

    results["finished_at_utc"] = datetime.now(timezone.utc).isoformat()
    (run_root / "results.json").write_text(json.dumps(results, indent=2) + "\n", encoding="utf-8")
    (run_root / "comparison.json").write_text(json.dumps({"comparisons": comparisons}, indent=2) + "\n", encoding="utf-8")
    print(run_root)
    return 1 if any("error" in outcome for outcome in results["outcomes"]) else 0


if __name__ == "__main__":
    raise SystemExit(main())

