use code_kb_core::{open_read_only, find_references_scoped, compute_blast_radius_scoped_with_ids};
use rusqlite::ffi;
use std::{ffi::{c_void, CStr}, path::Path, time::Instant};

unsafe extern "C" fn profile(_: u32, _: *mut c_void, statement: *mut c_void, elapsed: *mut c_void) -> i32 {
    unsafe {
        let stmt = statement.cast::<ffi::sqlite3_stmt>();
        let sql = ffi::sqlite3_expanded_sql(stmt);
        if !sql.is_null() {
            eprintln!("{}", serde_json::json!({
                "event": "sql_profile",
                "elapsed_ms": *(elapsed.cast::<u64>()) as f64 / 1_000_000.0,
                "sql": CStr::from_ptr(sql).to_string_lossy(),
                "template": CStr::from_ptr(ffi::sqlite3_sql(stmt)).to_string_lossy(),
                "fullscan_steps": ffi::sqlite3_stmt_status(stmt, ffi::SQLITE_STMTSTATUS_FULLSCAN_STEP, 0),
                "automatic_index_rows": ffi::sqlite3_stmt_status(stmt, ffi::SQLITE_STMTSTATUS_AUTOINDEX, 0),
                "vm_steps": ffi::sqlite3_stmt_status(stmt, ffi::SQLITE_STMTSTATUS_VM_STEP, 0),
                "sorts": ffi::sqlite3_stmt_status(stmt, ffi::SQLITE_STMTSTATUS_SORT, 0)
            }));
            ffi::sqlite3_free(sql.cast());
        }
    }
    0
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    let opened = Instant::now();
    let conn = open_read_only(Path::new(&args[2]))?;
    let open_ms = opened.elapsed().as_secs_f64() * 1000.0;
    if args[1] == "explain" {
        let sql = std::fs::read_to_string(&args[3])?;
        let mut stmt = conn.prepare(&format!("EXPLAIN QUERY PLAN {sql}"))?;
        let rows = stmt.query_map([], |r| Ok(serde_json::json!({
            "id": r.get::<_, i64>(0)?, "parent": r.get::<_, i64>(1)?,
            "detail": r.get::<_, String>(3)?
        })))?.collect::<Result<Vec<_>, _>>()?;
        println!("{}", serde_json::to_string_pretty(&rows)?);
        return Ok(());
    }
    unsafe { ffi::sqlite3_trace_v2(conn.handle(), ffi::SQLITE_TRACE_PROFILE as u32, Some(profile), std::ptr::null_mut()); }
    let started = Instant::now();
    let result = match args[1].as_str() {
        "sql" => {
            let sql = std::fs::read_to_string(&args[3])?;
            let mut stmt = conn.prepare(&sql)?;
            let columns = stmt.column_count();
            let mut cursor = stmt.query([])?;
            let mut rows = Vec::new();
            while let Some(row) = cursor.next()? {
                let mut values = Vec::new();
                for i in 0..columns {
                    values.push(match row.get_ref(i)? {
                        rusqlite::types::ValueRef::Null => serde_json::Value::Null,
                        rusqlite::types::ValueRef::Integer(v) => v.into(),
                        rusqlite::types::ValueRef::Real(v) => v.into(),
                        rusqlite::types::ValueRef::Text(v) => String::from_utf8_lossy(v).into_owned().into(),
                        rusqlite::types::ValueRef::Blob(_) => return Err("unexpected blob".into()),
                    });
                }
                rows.push(values);
            }
            serde_json::to_value(rows)?
        }
        "refs" => serde_json::to_value(find_references_scoped(&conn, &args[3], "callers", args[5].parse()?, false, Some(&args[4]))?)?,
        "blast" => serde_json::to_value(compute_blast_radius_scoped_with_ids(&conn, &[], &[], None, &[&args[3]], 2, 20)?)?,
        _ => return Err("unknown probe".into()),
    };
    println!("{}", serde_json::json!({
        "sqlite_version": rusqlite::version(), "open_ms": open_ms,
        "query_ms": started.elapsed().as_secs_f64() * 1000.0, "result": result
    }));
    Ok(())
}

